import numpy as np,csv,pathlib,json,datetime
p=pathlib.Path('outputs');x=np.load(p/'stage5_smad5_muscle_eur_reference_ld.npz');R=x['r'];v=x['variant'];d=list(csv.DictReader(open('work/stage5_susie_diagnostic/mak_fi_qtl_summary.csv')));assert list(v)==[r['variant'] for r in d];zq=np.array([float(r['qtl_beta'])/float(r['qtl_se']) for r in d]);zg=np.array([float(r['gwas_beta'])/float(r['gwas_se']) for r in d]);i,j=np.where(np.triu(np.abs(R)>0.999,1));q=np.abs(zq[i]-np.sign(R[i,j])*zq[j]);g=np.abs(zg[i]-np.sign(R[i,j])*zg[j]);rank=np.argsort(-np.maximum(q,g))[:100]
with open(p/'stage5_smad5_high_ld_z_check_top_pairs.csv','w',newline='') as f:
 w=csv.writer(f);w.writerow(['variant_1','variant_2','reference_r','qtl_z1','qtl_z2','gwas_z1','gwas_z2','aligned_qtl_z_difference','aligned_gwas_z_difference'])
 for z in rank:w.writerow([v[i[z]],v[j[z]],R[i[z],j[z]],zq[i[z]],zq[j[z]],zg[i[z]],zg[j[z]],q[z],g[z]])
a={'created_utc':datetime.datetime.now(datetime.timezone.utc).isoformat(),'variant_count':len(v),'reference_abs_r_threshold':.999,'high_ld_pairs':len(i),'qtl_z_difference_over_5':int((q>5).sum()),'gwas_z_difference_over_5':int((g>5).sum()),'max_qtl_abs_z_difference':float(q.max()),'max_gwas_abs_z_difference':float(g.max()),'interpretation':'Simple heuristic, not formal SuSiE LD consistency test; finite-reference and actual-sample LD can differ. Absence of large pairwise differences does not certify suitability.'};(p/'stage5_smad5_high_ld_z_check.json').write_text(json.dumps(a,indent=2)+'\n');print(json.dumps(a,indent=2))
